// OscarParserInit initializes any static state used to implement OscarParser. By default the
// static state used to implement the parser is lazily initialized during the first call to
// NewOscarParser(). You can call this function if you wish to initialize the static state ahead
// of time.
func OscarParserInit() {
	staticData := &OscarParserParserStaticData
	staticData.once.Do(oscarparserParserInit)
}

// NewOscarParser produces a new parser instance for the optional input antlr.TokenStream.
func NewOscarParser(input antlr.TokenStream) *OscarParser {
	OscarParserInit()
	this := new(OscarParser)
	this.BaseParser = antlr.NewBaseParser(input)
	staticData := &OscarParserParserStaticData
	this.Interpreter = antlr.NewParserATNSimulator(this, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	this.RuleNames = staticData.RuleNames
	this.LiteralNames = staticData.LiteralNames
	this.SymbolicNames = staticData.SymbolicNames
	this.GrammarFileName = "OscarParser.g4"

	return this
}

